/*
 * A231870  Elements of the sub-operad FCat(2) of TN generated by 00, 01, 02.
 * https://oeis.org/A231870
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 16, u16 n <= 57, u32 n <= 57, u64 n <= 57, u128 n <= 57,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Sequence A231870
 *
 * Elements of the sub‑operad FCat(2) of TN generated by 00, 01, 02.
 *
 * The words are enumerated as follows:
 *   w = d1 d2 … dk     with   d1 = 1
 *   and   d(i+1) ∈ [1, d(i)+2]   for i = 1 … k-1
 *
 * The value a(n) is the decimal concatenation of the n‑th word in this
 * lexicographic order (starting with n = 1).  For example, the first
 * words are 1, 11, 12, 13, 111, …
 *
 * Implementation: Dynamic programming builds the number of words
 * starting with a given digit and length (C[len][d]).  The array of
 * cumulative counts (cum[len]) gives the length of the nth word.
 * A mixed‑radix construction then recovers the word digit by digit,
 * and the last step concatenates the digits into a decimal number.
 */

#include <stdbool.h>

/* compile‑time constants ---------------------------------------------------- */

#define MAXLEN   20          /* enough for n ≤ 10 000 */
#define MAXLAST  (2*MAXLEN-1)/* maximal digit that can appear */

/* static data -------------------------------------------------------------- */
static seq_t C[MAXLEN+1][MAXLAST+1]; /* C[len][d] = #words of length len starting with digit d */
static seq_t cum[MAXLEN+1];           /* cum[len] = total words of length ≤ len starting with 1 */
static bool  initialized = false;

/* precomputation ------------------------------------------------------------ */
static void precompute(void)
{
    int len, d, nxt, limit;
    seq_t sum;

    /* base case: length 1, any starting digit yields exactly one word */
    for (d = 1; d <= MAXLAST; ++d)
        C[1][d] = 1;

    /* DP: build counts for longer lengths */
    for (len = 2; len <= MAXLEN; ++len) {
        for (d = 1; d <= MAXLAST; ++d) {
            sum   = 0;
            limit = d + 2;
            if (limit > MAXLAST) limit = MAXLAST;
            for (nxt = 1; nxt <= limit; ++nxt)
                sum += C[len-1][nxt];
            C[len][d] = sum;
        }
    }

    /* cumulative counts for words starting with ‘1’ */
    cum[0] = 0;
    for (len = 1; len <= MAXLEN; ++len)
        cum[len] = cum[len-1] + C[len][1];
}

/* main sequence function -------------------------------------------------- */
seq_t a(idx_t n)
{
    if (!initialized) {
        precompute();
        initialized = true;
    }
    if (n == 0)      /* undefined for n<1, return 0 as a safe fallback */
        return 0;

    /* determine the word length L such that cum[L‑1] < n ≤ cum[L] */
    int L = 1;
    while (L <= MAXLEN && cum[L] < n)
        ++L;
    if (L > MAXLEN)   /* safety: should not happen for n ≤ 10 000 */
        L = MAXLEN;

    /* rank of the word among all words of length L (0‑based) */
    seq_t rank = (seq_t)n - cum[L-1] - 1;

    /* reconstruct the word digit by digit */
    int digits[MAXLEN];
    int prev = 1;
    digits[0] = 1;

    for (int pos = 1; pos < L; ++pos) {
        /* remaining positions after the current one */
        int rest = L - pos - 1;
        for (int cand = 1; cand <= prev + 2; ++cand) {
            seq_t cnt = C[rest + 1][cand];
            if (rank < cnt) {
                digits[pos] = cand;
                prev = cand;
                break;
            } else
                rank -= cnt;
        }
    }

    /* concatenate digits into the decimal number */
    seq_t result = 0;
    for (int i = 0; i < L; ++i)
        result = result * 10 + (seq_t)digits[i];

    return result;
}
